    static let rhaiGrammarJSON = "{\n  \"_comment\": \"Rhai token grammar for colouring, not parsing (UI spec §1.1). Each surface generates its tokenizer from this file; a tolerant colorizer must never throw on partial input. Lexical rules are described, not compiled: the regexes are ECMAScript-flavoured and every surface re-expresses them in its own engine.\",\n  \"language\": \"rhai\",\n  \"keywords\": [\n    \"fn\", \"private\", \"let\", \"const\",\n    \"if\", \"else\", \"switch\",\n    \"while\", \"loop\", \"for\", \"in\", \"do\", \"until\",\n    \"return\", \"break\", \"continue\",\n    \"throw\", \"try\", \"catch\",\n    \"import\", \"export\", \"as\",\n    \"this\"\n  ],\n  \"literals\": [\"true\", \"false\", \"()\"],\n  \"operators\": [\n    \"+\", \"-\", \"*\", \"/\", \"%\", \"**\",\n    \"<<\", \">>\", \"&\", \"|\", \"^\", \"!\",\n    \"==\", \"!=\", \"<\", \">\", \"<=\", \">=\",\n    \"&&\", \"||\", \"??\",\n    \"=\", \"+=\", \"-=\", \"*=\", \"/=\", \"%=\", \"**=\", \"<<=\", \">>=\", \"&=\", \"|=\", \"^=\",\n    \"..\", \"..=\"\n  ],\n  \"punctuation\": [\"(\", \")\", \"{\", \"}\", \"[\", \"]\", \",\", \";\", \":\", \"::\", \".\", \"?.\", \"#{\", \"=>\"],\n  \"lexical\": {\n    \"comment\": {\n      \"line\": { \"start\": \"//\" },\n      \"block\": { \"start\": \"/*\", \"end\": \"*/\", \"nested\": true },\n      \"note\": \"An unterminated block comment colours to end of buffer.\"\n    },\n    \"string\": {\n      \"double\": { \"start\": \"\\\"\", \"end\": \"\\\"\", \"escape\": \"\\\\\", \"multiline\": false },\n      \"char\": { \"start\": \"'\", \"end\": \"'\", \"escape\": \"\\\\\", \"multiline\": false },\n      \"interpolated\": { \"start\": \"`\", \"end\": \"`\", \"escape\": \"\\\\\", \"multiline\": true, \"interpolation\": { \"start\": \"${\", \"end\": \"}\" } },\n      \"raw\": { \"start\": \"#\\\"\", \"end\": \"\\\"#\", \"multiline\": true },\n      \"note\": \"An unterminated string colours to end of line (to end of buffer for the multiline forms) and must not suppress colouring of later lines.\"\n    },\n    \"number\": {\n      \"pattern\": \"0x[0-9a-fA-F_]+|0o[0-7_]+|0b[01_]+|[0-9][0-9_]*(\\\\.[0-9][0-9_]*)?([eE][+-]?[0-9_]+)?\",\n      \"forms\": [\"int\", \"float\", \"hex\", \"octal\", \"binary\"]\n    },\n    \"identifier\": {\n      \"pattern\": \"[A-Za-z_][A-Za-z0-9_]*\"\n    }\n  },\n  \"map_token\": {\n    \"keyword\": \"keyword\",\n    \"literal\": \"boolean\",\n    \"string\": \"string\",\n    \"number\": \"number\",\n    \"comment\": \"comment\",\n    \"operator\": \"punct\",\n    \"punctuation\": \"punct\",\n    \"identifier\": \"text\"\n  },\n  \"map_token_note\": \"Values are the foundation syntax.* tokens (key/string/number/boolean/punct) plus the additive comment/keyword/text tokens (UI spec §1.1). `true`/`false`/`()` colour as boolean.\"\n}\n"

    static let rhaiAPIJSON = "{\n  \"_comment\": \"Rhai completion + hover catalog. Mirrors docs/superpowers/specs/2026-10-27-aitmproxy-plugin-system-design.md §'Tier 2 — Rhai scripting plugins' (hook table, 'flow object', 'Host functions') EXACTLY, so the drift guard (plan Task 12) can compare globals/flow/msg/dsl against the engine's registered set. Do not add an entry the plugin-system spec does not define. Entry names are fully qualified (`flow.request.headers.get`); a surface completes the last segment after the receiver chain. `kind` is object | property | method | function.\",\n  \"api_version\": \"1\",\n  \"hooks\": [\n    {\n      \"name\": \"load\",\n      \"signature\": \"load(reg)\",\n      \"description\": \"Called once at startup with the registration handle; register script commands and options here.\",\n      \"snippet\": \"fn load(reg) {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"configure\",\n      \"signature\": \"configure()\",\n      \"description\": \"Called after options change.\",\n      \"snippet\": \"fn configure() {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"on_request_headers\",\n      \"signature\": \"on_request_headers(flow)\",\n      \"description\": \"Fires on the RequestHeaders event, before the request body is read.\",\n      \"snippet\": \"fn on_request_headers(flow) {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"on_request\",\n      \"signature\": \"on_request(flow)\",\n      \"description\": \"Fires on the Request event, once the full request is available; mutate it before it goes upstream.\",\n      \"snippet\": \"fn on_request(flow) {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"on_response_headers\",\n      \"signature\": \"on_response_headers(flow)\",\n      \"description\": \"Fires on the ResponseHeaders event, before the response body is read.\",\n      \"snippet\": \"fn on_response_headers(flow) {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"on_response\",\n      \"signature\": \"on_response(flow)\",\n      \"description\": \"Fires on the Response event, once the full response is available.\",\n      \"snippet\": \"fn on_response(flow) {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"on_ws_start\",\n      \"signature\": \"on_ws_start(flow)\",\n      \"description\": \"Fires on the WsStart event, when a WebSocket connection is established.\",\n      \"snippet\": \"fn on_ws_start(flow) {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"on_ws_message\",\n      \"signature\": \"on_ws_message(flow, msg)\",\n      \"description\": \"Fires on the WsMessage event for each WebSocket frame; msg is the message object.\",\n      \"snippet\": \"fn on_ws_message(flow, msg) {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"on_ws_end\",\n      \"signature\": \"on_ws_end(flow)\",\n      \"description\": \"Fires on the WsEnd event, when a WebSocket connection closes.\",\n      \"snippet\": \"fn on_ws_end(flow) {\\n    $0\\n}\"\n    },\n    {\n      \"name\": \"on_error\",\n      \"signature\": \"on_error(flow, err)\",\n      \"description\": \"Fires on the Error event with the flow and the error.\",\n      \"snippet\": \"fn on_error(flow, err) {\\n    $0\\n}\"\n    }\n  ],\n  \"flow\": [\n    { \"name\": \"flow.id\", \"kind\": \"property\", \"signature\": \"flow.id -> string\", \"description\": \"The flow's id.\" },\n    { \"name\": \"flow.kind\", \"kind\": \"property\", \"signature\": \"flow.kind -> \\\"http\\\" | \\\"ws\\\"\", \"description\": \"Whether this is an HTTP or a WebSocket flow.\" },\n    { \"name\": \"flow.marks\", \"kind\": \"property\", \"signature\": \"flow.marks -> array\", \"description\": \"The marks on this flow (settable).\" },\n    { \"name\": \"flow.comment\", \"kind\": \"property\", \"signature\": \"flow.comment -> string\", \"description\": \"The operator comment on this flow (settable).\" },\n    { \"name\": \"flow.is_replay\", \"kind\": \"property\", \"signature\": \"flow.is_replay -> bool\", \"description\": \"True when this flow is a replay.\" },\n\n    { \"name\": \"flow.request\", \"kind\": \"object\", \"description\": \"The request side of the flow.\" },\n    { \"name\": \"flow.request.method\", \"kind\": \"property\", \"signature\": \"flow.request.method -> string\", \"description\": \"The request method (settable).\" },\n    { \"name\": \"flow.request.url\", \"kind\": \"property\", \"signature\": \"flow.request.url -> string\", \"description\": \"The full URL, scheme://authority/path?query (settable).\" },\n    { \"name\": \"flow.request.path\", \"kind\": \"property\", \"signature\": \"flow.request.path -> string\", \"description\": \"The request path (settable).\" },\n    { \"name\": \"flow.request.headers\", \"kind\": \"object\", \"description\": \"The request headers, a map-like object.\" },\n    { \"name\": \"flow.request.headers.get\", \"kind\": \"method\", \"signature\": \"get(k)\", \"description\": \"The value of header k.\" },\n    { \"name\": \"flow.request.headers.set\", \"kind\": \"method\", \"signature\": \"set(k, v)\", \"description\": \"Set header k to v.\" },\n    { \"name\": \"flow.request.headers.remove\", \"kind\": \"method\", \"signature\": \"remove(k)\", \"description\": \"Remove header k.\" },\n    { \"name\": \"flow.request.headers.has\", \"kind\": \"method\", \"signature\": \"has(k)\", \"description\": \"True when header k is present.\" },\n    { \"name\": \"flow.request.body\", \"kind\": \"property\", \"signature\": \"flow.request.body -> string | bytes\", \"description\": \"The request body (get/set).\" },\n    { \"name\": \"flow.request.set_json\", \"kind\": \"method\", \"signature\": \"set_json(obj)\", \"description\": \"Set the request body to the JSON encoding of obj.\" },\n    { \"name\": \"flow.request.query\", \"kind\": \"property\", \"signature\": \"flow.request.query -> map\", \"description\": \"The query parameters, a map-like object.\" },\n\n    { \"name\": \"flow.response\", \"kind\": \"object\", \"description\": \"The response side of the flow.\" },\n    { \"name\": \"flow.response.status\", \"kind\": \"property\", \"signature\": \"flow.response.status -> int\", \"description\": \"The response status code (settable).\" },\n    { \"name\": \"flow.response.headers\", \"kind\": \"object\", \"description\": \"The response headers, a map-like object.\" },\n    { \"name\": \"flow.response.headers.get\", \"kind\": \"method\", \"signature\": \"get(k)\", \"description\": \"The value of header k.\" },\n    { \"name\": \"flow.response.headers.set\", \"kind\": \"method\", \"signature\": \"set(k, v)\", \"description\": \"Set header k to v.\" },\n    { \"name\": \"flow.response.headers.remove\", \"kind\": \"method\", \"signature\": \"remove(k)\", \"description\": \"Remove header k.\" },\n    { \"name\": \"flow.response.headers.has\", \"kind\": \"method\", \"signature\": \"has(k)\", \"description\": \"True when header k is present.\" },\n    { \"name\": \"flow.response.body\", \"kind\": \"property\", \"signature\": \"flow.response.body -> string | bytes\", \"description\": \"The response body.\" },\n\n    { \"name\": \"flow.set_response\", \"kind\": \"method\", \"signature\": \"flow.set_response(status, headers, body)\", \"description\": \"Short-circuit before upstream: answer the request with this response.\" },\n    { \"name\": \"flow.intercept\", \"kind\": \"method\", \"signature\": \"flow.intercept()\", \"description\": \"Pause this flow for operator intervention.\" },\n    { \"name\": \"flow.resume\", \"kind\": \"method\", \"signature\": \"flow.resume()\", \"description\": \"Resume a paused flow.\" },\n    { \"name\": \"flow.kill\", \"kind\": \"method\", \"signature\": \"flow.kill()\", \"description\": \"Kill this flow.\" },\n    { \"name\": \"flow.backup\", \"kind\": \"method\", \"signature\": \"flow.backup()\", \"description\": \"Snapshot the flow so it can be reverted.\" },\n    { \"name\": \"flow.revert\", \"kind\": \"method\", \"signature\": \"flow.revert()\", \"description\": \"Restore the flow to its last backup.\" },\n    { \"name\": \"flow.mark\", \"kind\": \"method\", \"signature\": \"flow.mark(tag)\", \"description\": \"Add a mark to this flow.\" }\n  ],\n  \"msg\": [\n    { \"name\": \"msg.direction\", \"kind\": \"property\", \"signature\": \"msg.direction -> \\\"c2s\\\" | \\\"s2c\\\"\", \"description\": \"Frame direction: client-to-server or server-to-client.\" },\n    { \"name\": \"msg.opcode\", \"kind\": \"property\", \"signature\": \"msg.opcode -> \\\"text\\\" | \\\"binary\\\" | \\\"ping\\\" | \\\"pong\\\" | \\\"close\\\"\", \"description\": \"The WebSocket opcode.\" },\n    { \"name\": \"msg.text\", \"kind\": \"property\", \"signature\": \"msg.text -> string\", \"description\": \"The frame as text (settable).\" },\n    { \"name\": \"msg.data\", \"kind\": \"property\", \"signature\": \"msg.data -> bytes\", \"description\": \"The frame payload as bytes.\" },\n    { \"name\": \"msg.set_text\", \"kind\": \"method\", \"signature\": \"msg.set_text(s)\", \"description\": \"Replace the frame payload with the text s.\" },\n    { \"name\": \"msg.set_bytes\", \"kind\": \"method\", \"signature\": \"msg.set_bytes(b)\", \"description\": \"Replace the frame payload with the bytes b.\" },\n    { \"name\": \"msg.drop\", \"kind\": \"method\", \"signature\": \"msg.drop()\", \"description\": \"Do not forward this frame.\" }\n  ],\n  \"globals\": [\n    { \"name\": \"log\", \"kind\": \"function\", \"signature\": \"log(msg)\", \"description\": \"Write msg to the script's log.\" },\n    { \"name\": \"log.info\", \"kind\": \"function\", \"signature\": \"log.info(msg)\", \"description\": \"Log at info level.\" },\n    { \"name\": \"log.warn\", \"kind\": \"function\", \"signature\": \"log.warn(msg)\", \"description\": \"Log at warn level.\" },\n    { \"name\": \"log.error\", \"kind\": \"function\", \"signature\": \"log.error(msg)\", \"description\": \"Log at error level.\" },\n\n    { \"name\": \"http.send\", \"kind\": \"function\", \"signature\": \"http.send(#{ method, url, headers, body }) -> #{ status, headers, body, flow_id }\", \"description\": \"Send an HTTP request through the proxy's own client (scope- and rate-gated); the exchange is captured as a flow.\" },\n\n    { \"name\": \"browser.navigate\", \"kind\": \"function\", \"signature\": \"browser.navigate(url)\", \"description\": \"Navigate the embedded browser to url (scope- and SSRF-gated).\" },\n    { \"name\": \"browser.click\", \"kind\": \"function\", \"signature\": \"browser.click(selector_or_xy)\", \"description\": \"Click an element by selector, or a point by coordinates.\" },\n    { \"name\": \"browser.type\", \"kind\": \"function\", \"signature\": \"browser.type(selector, text)\", \"description\": \"Type text into the element matching selector.\" },\n    { \"name\": \"browser.screenshot\", \"kind\": \"function\", \"signature\": \"browser.screenshot() -> bytes\", \"description\": \"Capture the page as PNG bytes.\" },\n    { \"name\": \"browser.eval\", \"kind\": \"function\", \"signature\": \"browser.eval(expr) -> value\", \"description\": \"Evaluate a JavaScript expression in the page.\" },\n    { \"name\": \"browser.get_dom\", \"kind\": \"function\", \"signature\": \"browser.get_dom() -> string\", \"description\": \"The page's DOM as a string.\" },\n\n    { \"name\": \"store.get\", \"kind\": \"function\", \"signature\": \"store.get(id) -> flow view\", \"description\": \"Read one flow from the flow store by id.\" },\n    { \"name\": \"store.query\", \"kind\": \"function\", \"signature\": \"store.query(#{ host, method, status, kind, is_replay }) -> array of flow views\", \"description\": \"Query the flow store; returns matching flow views.\" },\n\n    { \"name\": \"scope.add\", \"kind\": \"function\", \"signature\": \"scope.add(host)\", \"description\": \"Add host to the authorised scope.\" },\n    { \"name\": \"scope.list\", \"kind\": \"function\", \"signature\": \"scope.list() -> array\", \"description\": \"The hosts currently in scope.\" },\n\n    { \"name\": \"option\", \"kind\": \"function\", \"signature\": \"option(name) -> value\", \"description\": \"The value of an option set at load.\" },\n    { \"name\": \"halt\", \"kind\": \"function\", \"signature\": \"halt()\", \"description\": \"Return from a hook to halt the plugin chain (Verdict::Halt). Returning nothing continues the chain.\" }\n  ],\n  \"dsl\": [\n    { \"name\": \"b64_encode\", \"kind\": \"function\", \"signature\": \"b64_encode(s)\", \"description\": \"Base64-encode s.\" },\n    { \"name\": \"b64_decode\", \"kind\": \"function\", \"signature\": \"b64_decode(s)\", \"description\": \"Base64-decode s.\" },\n    { \"name\": \"url_encode\", \"kind\": \"function\", \"signature\": \"url_encode(s)\", \"description\": \"Percent-encode s for use in a URL.\" },\n    { \"name\": \"hex_encode\", \"kind\": \"function\", \"signature\": \"hex_encode(s)\", \"description\": \"Hex-encode s.\" },\n    { \"name\": \"sha256\", \"kind\": \"function\", \"signature\": \"sha256(s)\", \"description\": \"SHA-256 digest of s.\" },\n    { \"name\": \"md5\", \"kind\": \"function\", \"signature\": \"md5(s)\", \"description\": \"MD5 digest of s.\" },\n    { \"name\": \"rand_text_alpha\", \"kind\": \"function\", \"signature\": \"rand_text_alpha(n)\", \"description\": \"A random string of n letters.\" },\n    { \"name\": \"rand_int\", \"kind\": \"function\", \"signature\": \"rand_int(a, b)\", \"description\": \"A random integer between a and b.\" },\n    { \"name\": \"regex_match\", \"kind\": \"function\", \"signature\": \"regex_match(pat, s)\", \"description\": \"True when pattern pat matches s.\" },\n    { \"name\": \"regex_extract\", \"kind\": \"function\", \"signature\": \"regex_extract(pat, s, group)\", \"description\": \"The capture group of pat's match in s.\" }\n  ]\n}\n"

    static let pocYAMLSchemaJSON = "{\n  \"_comment\": \"PoC YAML key tree for schema-aware completion + hover (UI spec §1.1). Content mirrors docs/superpowers/specs/2026-10-27-aitmproxy-poc-language-design.md §'Document structure', §'Step types', §'Matcher / extractor DSL', §'Success / assertion model' and its four worked examples. Node = { type, description, required?, enum?, keys?, items?, one_of_keys?, $ref? }. `keys` is the child key map of a `map`; `items` is the element node of a `list`; `$ref` is `#/$defs/<name>`. Completion walks the YAML nesting: key position -> the enclosing node's `keys`; after `key:` -> that node's `enum` (or true/false for `boolean`). If the builder's validation poc-schema ships, regenerate this from it.\",\n  \"type\": \"map\",\n  \"description\": \"A PoC document.\",\n  \"keys\": {\n    \"id\": { \"type\": \"string\", \"required\": true, \"description\": \"Unique PoC identifier (no spaces).\" },\n    \"info\": {\n      \"type\": \"map\",\n      \"required\": true,\n      \"description\": \"Identification metadata for the PoC.\",\n      \"keys\": {\n        \"name\": { \"type\": \"string\", \"description\": \"Human title.\" },\n        \"author\": { \"type\": \"string\", \"description\": \"Optional author.\" },\n        \"severity\": {\n          \"type\": \"enum\",\n          \"enum\": [\"info\", \"low\", \"medium\", \"high\", \"critical\"],\n          \"description\": \"How serious the finding is; maps to Severity.\"\n        },\n        \"description\": { \"type\": \"string\", \"description\": \"What the finding is (no fix prose).\" },\n        \"reference\": { \"type\": \"list\", \"description\": \"URLs, CVE or CWE references.\", \"items\": { \"type\": \"string\", \"description\": \"One reference.\" } },\n        \"tags\": { \"type\": \"list\", \"description\": \"Tags for selection and reporting.\", \"items\": { \"type\": \"string\", \"description\": \"One tag.\" } },\n        \"cwe\": { \"type\": \"string\", \"description\": \"Optional CWE identifier, e.g. CWE-79.\" },\n        \"metadata\": { \"type\": \"map\", \"description\": \"Arbitrary key: value metadata.\" }\n      }\n    },\n    \"variables\": {\n      \"type\": \"list\",\n      \"description\": \"Reusable {{placeholders}} with optional defaults.\",\n      \"items\": {\n        \"type\": \"map\",\n        \"description\": \"One variable definition.\",\n        \"keys\": {\n          \"name\": { \"type\": \"string\", \"description\": \"The variable name, referenced as {{name}}.\" },\n          \"default\": { \"type\": \"any\", \"description\": \"Default value; may be a DSL expression wrapped in {{ }}, evaluated once at run start.\" },\n          \"description\": { \"type\": \"string\", \"description\": \"What the variable is for.\" },\n          \"required\": { \"type\": \"boolean\", \"description\": \"Whether the caller must supply a value (default false).\" }\n        }\n      }\n    },\n    \"steps\": {\n      \"type\": \"list\",\n      \"required\": true,\n      \"description\": \"Ordered steps; each entry has exactly one step key.\",\n      \"items\": {\n        \"type\": \"map\",\n        \"description\": \"One step.\",\n        \"one_of_keys\": [\"http\", \"browser\", \"extract\", \"script\"],\n        \"keys\": {\n          \"http\": {\n            \"type\": \"map\",\n            \"description\": \"Send an HTTP request through the proxy's guarded client.\",\n            \"keys\": {\n              \"method\": { \"type\": \"string\", \"description\": \"HTTP method: GET, POST, ...\" },\n              \"url\": { \"type\": \"string\", \"description\": \"Full URL (templated).\" },\n              \"path\": { \"type\": \"string\", \"description\": \"Path relative to {{BaseURL}} (templated).\" },\n              \"headers\": { \"type\": \"map\", \"description\": \"Request headers (templated).\" },\n              \"body\": { \"type\": \"string\", \"description\": \"Request body (templated); use raw for full control.\" },\n              \"raw\": { \"type\": \"string\", \"description\": \"Full raw HTTP text with placeholders (nuclei RAW mode).\" },\n              \"extract\": { \"type\": \"list\", \"description\": \"Post-response extractors.\", \"items\": { \"$ref\": \"#/$defs/extractor\" } },\n              \"matchers\": { \"type\": \"list\", \"description\": \"Per-step matchers.\", \"items\": { \"$ref\": \"#/$defs/matcher\" } },\n              \"matchers-condition\": {\n                \"type\": \"enum\",\n                \"enum\": [\"and\", \"or\"],\n                \"description\": \"How this step's matchers combine.\"\n              }\n            }\n          },\n          \"browser\": {\n            \"type\": \"map\",\n            \"description\": \"Drive the embedded browser with one action.\",\n            \"keys\": {\n              \"action\": {\n                \"type\": \"enum\",\n                \"enum\": [\"navigate\", \"click\", \"type\", \"eval\", \"screenshot\"],\n                \"description\": \"Which browser action to run.\"\n              },\n              \"url\": { \"type\": \"string\", \"description\": \"Page to load (navigate); SSRF-guarded.\" },\n              \"target\": { \"type\": \"string\", \"description\": \"Selector or x,y to click (click).\" },\n              \"selector\": { \"type\": \"string\", \"description\": \"Element to type into (type).\" },\n              \"text\": { \"type\": \"string\", \"description\": \"Text to type (type).\" },\n              \"expr\": { \"type\": \"string\", \"description\": \"JavaScript to run; bind or assert its value (eval).\" },\n              \"label\": { \"type\": \"string\", \"description\": \"Artifact label for the PNG (screenshot).\" }\n            }\n          },\n          \"extract\": { \"$ref\": \"#/$defs/extractor\" },\n          \"script\": {\n            \"type\": \"map\",\n            \"description\": \"Rhai escape hatch using the plugin-system Rhai API, plus vars.get/vars.set.\",\n            \"keys\": {\n              \"name\": { \"type\": \"string\", \"description\": \"Optional label; success can reference the step's verdict by this name.\" },\n              \"script\": { \"type\": \"string\", \"description\": \"Rhai source; may `return pass` or `return fail`.\" }\n            }\n          }\n        }\n      }\n    },\n    \"success\": {\n      \"type\": \"map\",\n      \"required\": true,\n      \"description\": \"What 'triggered' means: an assertion tree evaluated after all steps. A bare matcher, or a list of matchers, is also allowed.\",\n      \"keys\": {\n        \"all\": { \"type\": \"list\", \"description\": \"True when every assertion holds.\", \"items\": { \"$ref\": \"#/$defs/matcher\" } },\n        \"any\": { \"type\": \"list\", \"description\": \"True when at least one assertion holds.\", \"items\": { \"$ref\": \"#/$defs/matcher\" } },\n        \"not\": { \"$ref\": \"#/$defs/matcher\" }\n      }\n    }\n  },\n  \"$defs\": {\n    \"matcher\": {\n      \"type\": \"map\",\n      \"description\": \"A matcher or assertion over a response, the page, or a step's verdict.\",\n      \"keys\": {\n        \"type\": {\n          \"type\": \"enum\",\n          \"enum\": [\"status\", \"word\", \"regex\", \"size\", \"binary\", \"dsl\", \"browser-eval\"],\n          \"description\": \"The matcher kind.\"\n        },\n        \"status\": { \"type\": \"integer\", \"description\": \"Expected status code (status).\" },\n        \"word\": { \"type\": \"string\", \"description\": \"Literal word to find (word).\" },\n        \"regex\": { \"type\": \"string\", \"description\": \"Pattern to match (regex).\" },\n        \"size\": { \"type\": \"integer\", \"description\": \"Expected content length (size).\" },\n        \"binary\": { \"type\": \"string\", \"description\": \"Hex byte signature (binary).\" },\n        \"dsl\": { \"type\": \"string\", \"description\": \"DSL expression over status_code, body, all_headers, content_length and extracted vars (dsl).\" },\n        \"expr\": { \"type\": \"string\", \"description\": \"JavaScript to evaluate in the page (browser-eval).\" },\n        \"equals\": { \"type\": \"string\", \"description\": \"Expected value of expr (browser-eval).\" },\n        \"encoding\": { \"type\": \"enum\", \"enum\": [\"hex\"], \"description\": \"Value encoding for word.\" },\n        \"part\": {\n          \"type\": \"enum\",\n          \"enum\": [\"body\", \"header\", \"all\"],\n          \"description\": \"Which part of the response to match (default body).\"\n        },\n        \"condition\": {\n          \"type\": \"enum\",\n          \"enum\": [\"and\", \"or\"],\n          \"description\": \"How a matcher's own values combine.\"\n        },\n        \"negative\": { \"type\": \"boolean\", \"description\": \"Invert the match.\" },\n        \"internal\": { \"type\": \"boolean\", \"description\": \"Precondition only; not printed.\" },\n        \"name\": { \"type\": \"string\", \"description\": \"Label for the matcher, referenceable from success.\" }\n      }\n    },\n    \"extractor\": {\n      \"type\": \"map\",\n      \"description\": \"Extracts a value from a response or the page; a named extractor binds a variable.\",\n      \"keys\": {\n        \"name\": { \"type\": \"string\", \"description\": \"Binds a variable for later steps.\" },\n        \"type\": {\n          \"type\": \"enum\",\n          \"enum\": [\"regex\", \"json\", \"kval\", \"dsl\", \"browser-eval\"],\n          \"description\": \"The extractor kind.\"\n        },\n        \"from\": {\n          \"type\": \"enum\",\n          \"enum\": [\"body\", \"header\", \"all\"],\n          \"description\": \"Which part of the response to extract from.\"\n        },\n        \"regex\": { \"type\": \"string\", \"description\": \"Pattern with capture groups (regex).\" },\n        \"group\": { \"type\": \"integer\", \"description\": \"Capture group to take (regex).\" },\n        \"json\": { \"type\": \"string\", \"description\": \"JSONPath or jq expression (json).\" },\n        \"kval\": { \"type\": \"string\", \"description\": \"Header or cookie key, dashes as underscores (kval).\" },\n        \"expr\": { \"type\": \"string\", \"description\": \"Expression to evaluate (dsl, browser-eval).\" },\n        \"internal\": { \"type\": \"boolean\", \"description\": \"Pass between steps without printing.\" }\n      }\n    }\n  }\n}\n"
}
